const { Worker } = require('node:worker_threads');

class WorkerPool {
  /**
   * @param {number} size number of worker threads
   * @param {string} workerScript path to the worker script
   */
  constructor(size, workerScript) {
    if (!Number.isInteger(size) || size < 1) {
      throw new RangeError(`size must be a positive integer, got ${size}`);
    }
    this.size = size;
    this.workerScript = workerScript;

    this._free = [];                 // idle workers
    this._queue = [];                // tasks waiting for a free worker
    this._pending = new Map();       // id -> { resolve, reject, worker }
    this._nextId = 0;
    this._destroyed = false;

    // Instrumentation
    this.stats = {
      busy: 0,
      peakBusy: 0,
      completed: 0,
      failed: 0,
      queued: 0,
    };

    this._workers = [];
    for (let i = 0; i < size; i++) {
      this._spawnWorker();
    }
  }

  _spawnWorker() {
    const worker = new Worker(this.workerScript);
    worker.unref === undefined; // keep explicit ref behavior; workers ref by default

    worker.on('message', ({ id, result, error }) => {
      const entry = this._pending.get(id);
      if (!entry) return; // stale message (e.g. after destroy)
      this._pending.delete(id);

      if (error !== undefined) {
        this.stats.failed++;
        entry.reject(new Error(error));
      } else {
        this.stats.completed++;
        entry.resolve(result);
      }
      this._releaseWorker(worker);
    });

    worker.on('error', (err) => {
      // Unexpected worker crash (not a task error): fail its in-flight task.
      for (const [id, entry] of this._pending) {
        if (entry.worker === worker) {
          this._pending.delete(id);
          this.stats.failed++;
          entry.reject(err);
          break;
        }
      }
      this._replaceWorker(worker);
    });

    worker.on('exit', (code) => {
      if (code !== 0 && !this._destroyed) this._replaceWorker(worker);
    });

    this._workers.push(worker);
    this._free.push(worker);
    return worker;
  }

  _replaceWorker(deadWorker) {
    const idx = this._workers.indexOf(deadWorker);
    if (idx !== -1) this._workers.splice(idx, 1);
    const freeIdx = this._free.indexOf(deadWorker);
    if (freeIdx !== -1) this._free.splice(freeIdx, 1);
    if (!this._destroyed) this._spawnWorker();
    else this._drainIfIdle();
  }

  _releaseWorker(worker) {
    this.stats.busy--;
    const next = this._queue.shift();
    if (next) {
      this.stats.queued--;
      this._dispatch(worker, next.id, next.task, next.resolve, next.reject);
    } else {
      this._free.push(worker);
      this._drainIfIdle();
    }
  }

  _drainIfIdle() {
    // Allow the event loop to finish when nothing is running or queued.
    if (this._destroyed && this._pending.size === 0 && this._queue.length === 0) return;
  }

  _dispatch(worker, id, task, resolve, reject) {
    this.stats.busy++;
    if (this.stats.busy > this.stats.peakBusy) this.stats.peakBusy = this.stats.busy;
    this._pending.set(id, { resolve, reject, worker });
    worker.postMessage({ id, task });
  }

  /**
   * Run a task ({op:'fib'|'sha', n}) on a pool worker.
   * @returns {Promise<any>}
   */
  run(task) {
    if (this._destroyed) {
      return Promise.reject(new Error('WorkerPool is destroyed'));
    }
    const id = ++this._nextId;
    return new Promise((resolve, reject) => {
      const freeWorker = this._free.pop();
      if (freeWorker) {
        this._dispatch(freeWorker, id, task, resolve, reject);
      } else {
        this.stats.queued++;
        this._queue.push({ id, task, resolve, reject });
      }
    });
  }

  /** Terminate all workers and reject anything still pending/queued. */
  async destroy() {
    if (this._destroyed) return;
    this._destroyed = true;

    const error = new Error('WorkerPool destroyed');
    for (const [, entry] of this._pending) {
      entry.reject(error);
    }
    this._pending.clear();

    for (const q of this._queue) {
      q.reject(error);
    }
    this._queue.length = 0;
    this.stats.queued = 0;
    this.stats.busy = 0;

    await Promise.all(this._workers.map((w) => w.terminate()));
    this._workers.length = 0;
    this._free.length = 0;
  }

  get busyCount() {
    return this.stats.busy;
  }
}

module.exports = { WorkerPool };
