result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/pool.test.js", "content": "'use strict';

const test = require('node:test');
const assert = require('node:assert');
const crypto = require('node:crypto');

const { WorkerPool } = require('../pool.js');

function expectedFib(n) {
  let a = 0n, b = 1n;
  for (let i = 0; i < n; i++) [a, b] = [b, a + b];
  return a.toString();
}

function expectedShaRounds(n) {
  let h = Buffer.from('pool-worker-seed');
  for (let i = 0; i < n; i++) h = crypto.createHash('sha256').update(h).digest();
  return h.toString('hex');
}

test('20 concurrent tasks on pool size 4 resolve correctly with peak busy <= 4', async () => {
  const pool = new WorkerPool(4, new URL('../worker.js', import.meta.url).pathname);

  // Build 20 mixed tasks.
  const tasks = [];
  for (let i = 0; i < 10; i++) tasks.push({ op: 'fib', n: 5 + i * 3 });
  for (let i = 0; i < 10; i++) tasks.push({ op: 'sha', n: 20 + i * 7 });

  // Track busy workers from the outside via instrumentation sampling.
  const sampler = setInterval(() => {
    assert.ok(pool.busyCount <= 4, `busyCount ${pool.busyCount} exceeded pool size`);
  }, 1);

  const results = await Promise.all(tasks.map((t) => pool.run(t)));
  clearInterval(sampler);

  results.forEach((res, i) => {
    const t = tasks[i];
    if (t.op === 'fib') assert.strictEqual(res, expectedFib(t.n), `fib(${t.n})`);
    else assert.strictEqual(res, expectedShaRounds(t.n), `sha(${t.n})`);
  });

  assert.strictEqual(pool.stats.completed, 20);
  assert.ok(
    pool.stats.peakBusy <= 4,
    `peakBusy ${pool.stats.peakBusy} must be <= 4`
  );
  assert.ok(pool.stats.peakBusy > 1, 'expected real concurrency, peakBusy was 1');
  assert.strictEqual(pool.stats.queued + pool.busyCount, 0);

  await pool.destroy();
});

test('a failing task rejects only its own promise and the worker survives', async () => {
  const pool = new WorkerPool(4, new URL('../worker.js', import.meta.url).pathname);

  await assert.rejects(() => pool.run({ op: 'nope' }), /Unknown op/);
  assert.strictEqual(pool.stats.failed, 1);
  assert.strictEqual(pool.stats.completed, 0);

  // The same worker must still be usable after reporting an error.
  const before = pool._workers.length;
  const fibResult = await pool.run({ op: 'fib', n: 30 });
  assert.strictEqual(fibResult, expectedFib(30));

  // Interleave failures with successes concurrently; only failures reject.
  const jobs = [
    Promise.resolve('ok-1'),
    pool.run({ op: 'boom' }).then(() => 'bad', (e) => `rejected:${e.message}`),
    pool.run({ op: 'fib', n: 10 }),
    pool.run({ op: 'sha', n: 50 }),
    pool.run({ op: 'also-bad' }).catch((e) => `rejected:${e.message}`),
  ];
  const outcomes = await Promise.all(jobs);

  assert.match(outcomes[1], /^rejected:/);
  assert.strictEqual(outcomes[2], expectedFib(10));
  assert.strictEqual(outcomes[3], expectedShaRounds(50));
  assert.match(outcomes[4], /^rejected:/);

  assert.strictEqual(pool._workers.length, before, 'worker count unchanged');
  assert.strictEqual(pool.stats.completed, 3);
  assert.strictEqual(pool.stats.failed, 3);

  await pool.destroy();
});

test('destroy() terminates all workers so the process can exit cleanly', async () => {
  const pool = new WorkerPool(2, new URL('../worker.js', import.meta.url).pathname);

  // Keep the workers busy while destroying.
  const slow = pool.run({ op: 'sha', n: 100000 });
  const queued = pool.run({ op: 'fib', n: 10 });

  await pool.destroy();

  await assert.rejects(() => slow, /destroyed/);
  await assert.rejects(() => queued, /destroyed/);
  await assert.rejects(() => pool.run({ op: 'fib', n: 5 }), /destroyed/);
  assert.strictEqual(pool._workers.length, 0);
});
"})
